#!/usr/bin/env bash
# Sync the PDF engine vendored in the `xlsx-to-pdf` crate from `pdf/src`.
#
# The `xlsx-to-pdf` crate is published on its own, so it cannot depend on the
# unpublished `ironcalc_pdf` crate. The engine modules are copied verbatim
# except for `crate::` -> `super::` (the modules live under `crate::pdf` here).
#
# `src/pdf/mod.rs` is a hand-written adaptation of `pdf/src/lib.rs` and is not
# generated by this script.
#
# Usage:
#   ./packages/xlsx-to-pdf/sync-pdf.sh          # update the vendored copy
#   ./packages/xlsx-to-pdf/sync-pdf.sh --check  # fail if the copy is stale
set -euo pipefail

root="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
src="$root/pdf/src"
dst="$root/packages/xlsx-to-pdf/wasm/src/pdf"

check=false
if [ "${1:-}" = "--check" ]; then
  check=true
fi

status=0
for module in error layout options renderer; do
  if $check; then
    if ! diff -u <(sed 's/crate::/super::/g' "$src/$module.rs") "$dst/$module.rs"; then
      status=1
    fi
  else
    sed 's/crate::/super::/g' "$src/$module.rs" > "$dst/$module.rs"
  fi
done

if [ "$status" -ne 0 ]; then
  echo "error: vendored PDF engine is out of date; run 'make sync-pdf'" >&2
fi

exit "$status"
